import { FloatingLabelField } from "@/components/design-for-ai/input-floating-label";

const isEmail = (value: string) => /^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(value.trim());

<FloatingLabelField
  type="email"
  autoComplete="email"
  label="Work email"
  helper="We’ll send receipts and invoices here."
  errorText="Add a domain, like ana@studio.co"
  successText="Looks good. Receipts go here."
  validate={isEmail}
  maxLength={40}
  value={email}
  onValueChange={setEmail}
/>

<FloatingLabelField
  label="Company"
  size="lg"
  suffix="Optional"
  maxLength={60}
/>
